import * as THREE from 'three';

/**
 * Dynamic attribute re-evaluation pass (Phase BO, stage 2).
 *
 * The generalisation of the Phase BN spike: ONE fullscreen pass
 * that re-evaluates the attribute slot expressions against the
 * baked attribute texture and writes the replacement texture
 * the consumers then read. The fragment shader is generated by
 * lib/expressionGlsl.ts (buildAttrDynFragment) from the same
 * compiled ASTs the stage-1 bake evaluates, with t = the sim
 * clock — so the pass is stateless (it always reads the BAKE,
 * never its own previous output), which is what keeps the
 * deterministic render reproducible.
 *
 * The wiring (sceneGpgpuSystem) owns the lifecycle: it builds
 * this pass only while stage 2 is enabled with at least one
 * compilable expression, rebuilds it when the signature
 * (enabled / exprs / names / interval / texSize) changes, and
 * disposes it otherwise. While disabled the pass never exists
 * and the consumers receive the bake texture verbatim.
 */
const ATTR_DYN_VERT = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position.xy, 0.0, 1.0);
}
`;

export class GpgpuAttrDynPass {
  private rt: THREE.WebGLRenderTarget;
  private mat: THREE.ShaderMaterial;
  private scene = new THREE.Scene();
  private cam = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  private geo: THREE.PlaneGeometry;

  constructor(texSize: number, fragmentShader: string) {
    this.rt = new THREE.WebGLRenderTarget(texSize, texSize, {
      type: THREE.FloatType,
      format: THREE.RGBAFormat,
      minFilter: THREE.NearestFilter,
      magFilter: THREE.NearestFilter,
      depthBuffer: false,
      stencilBuffer: false,
    });
    this.mat = new THREE.ShaderMaterial({
      uniforms: {
        uSrc: { value: null as THREE.Texture | null },
        uTime: { value: 0 },
      },
      vertexShader: ATTR_DYN_VERT,
      fragmentShader,
      depthTest: false,
      depthWrite: false,
    });
    this.geo = new THREE.PlaneGeometry(2, 2);
    const mesh = new THREE.Mesh(this.geo, this.mat);
    mesh.frustumCulled = false;
    this.scene.add(mesh);
  }

  /** Re-evaluate against the bake texture at sim time `time`
   *  and return the output texture (stable across calls — the
   *  wiring holds it between interval frames). */
  run(gl: THREE.WebGLRenderer, src: THREE.Texture, time: number): THREE.Texture {
    this.mat.uniforms.uSrc.value = src;
    this.mat.uniforms.uTime.value = time;
    const prev = gl.getRenderTarget();
    gl.setRenderTarget(this.rt);
    gl.render(this.scene, this.cam);
    gl.setRenderTarget(prev);
    return this.rt.texture;
  }

  dispose(): void {
    this.rt.dispose();
    this.mat.dispose();
    this.geo.dispose();
  }
}
